target.css:
:root {
  --ink: #26342d;
  --paper: #fffdf7;
  --tomato: #d95d45;
  --sage: #dce8d3;
  --cream: #f8edcf;
  --line: #d7d5ca;
}

* {
  box-sizing: border-box;
}

.potluck-card {
  width: 480px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.potluck-card header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 18px 14px;
  border-bottom: 1px solid var(--line);
}

.host .kicker {
  margin: 0 0 4px;
  color: var(--tomato);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 1.1px;
}

.host h2 {
  margin: 0;
  font-size: 21px;
  line-height: 1.1;
}

.date {
  width: 48px;
  padding: 6px 4px;
  color: var(--paper);
  background: var(--tomato);
  border-radius: 10px;
  font-size: 10px;
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: .7px;
  text-align: center;
}

.date strong {
  display: block;
  margin-top: 2px;
  font-size: 19px;
  letter-spacing: 0;
}

.details {
  display: grid;
  grid-template-columns: 1fr 176px;
  gap: 14px;
  padding: 14px 18px;
}

.info {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin: 0;
}

.info div {
  min-width: 0;
}

.info dt {
  margin-bottom: 3px;
  color: var(--tomato);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .6px;
  text-transform: uppercase;
}

.info dd {
  margin: 0;
  font-size: 12px;
  font-weight: 650;
  line-height: 1.3;
}

.dish {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 9px;
  background: var(--cream);
  border-radius: 11px;
}

.dish-icon {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  background: var(--paper);
  border-radius: 50%;
  font-size: 18px;
}

.dish p {
  margin: 0;
  font-size: 11px;
  line-height: 1.35;
}

.dish strong {
  font-size: 12px;
}

.potluck-card footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 18px;
  background: var(--sage);
}

.tags {
  display: flex;
  gap: 5px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.tags li {
  padding: 4px 7px;
  border: 1px solid var(--ink);
  border-radius: 999px;
  font-size: 10px;
  font-weight: 700;
}

.actions {
  display: flex;
  gap: 7px;
}

.actions button {
  padding: 8px 10px;
  border-radius: 8px;
  font-size: 11px;
  font-weight: 800;
  cursor: pointer;
}

.decline {
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--ink);
}

.accept {
  color: var(--paper);
  background: var(--ink);
  border: 1px solid var(--ink);
}

